local CrumbTrayMaker = {}
local PRODUCTS = {
    iron_crumbtray = { name = "Železni pladenj za drobtine", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni pladenj za drobtine za pekove." },
    bronze_crumbtray = { name = "Bronast pladenj za drobtine", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast pladenj za drobtine za pekove." },
    silver_crumbtray = { name = "Srebrn pladenj za drobtine", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn pladenj za drobtine za pekove." },
    gilded_crumbtray = { name = "Pozlačen pladenj za drobtine", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen pladenj za drobtine za pekove." },
    jewel_set_crumbtray = { name = "Draguljast pladenj za drobtine", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast pladenj za drobtine za pekove." },
    royal_sovereign_crumbtray = { name = "Kraljevski suveren pladenj za drobtine", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren pladenj za drobtine z biseri za krono." },
}
local BUILDINGS = {
    crumbtray_workshop = { name = "Crumbtray delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    crumbtray_house = { name = "Crumbtray hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_crumbtray_atelier = { name = "Mojstrski crumbtray atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_crumbtray_palace = { name = "Suverena crumbtray palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CrumbTrayMaker.ironStock=12; CrumbTrayMaker.bronzeStock=10; CrumbTrayMaker.woodStock=14; CrumbTrayMaker.leatherStock=12; CrumbTrayMaker.silverStock=8; CrumbTrayMaker.goldStock=6; CrumbTrayMaker.jewelStock=4; CrumbTrayMaker.pearlStock=4
CrumbTrayMaker.productStock = {}; CrumbTrayMaker.buildings = {}; CrumbTrayMaker.maker = nil; CrumbTrayMaker.activeMaking = {}; CrumbTrayMaker.totalProducts = 0; CrumbTrayMaker.dayTimer = 0
function CrumbTrayMaker.init() CrumbTrayMaker.ironStock=12; CrumbTrayMaker.bronzeStock=10; CrumbTrayMaker.woodStock=14; CrumbTrayMaker.leatherStock=12; CrumbTrayMaker.silverStock=8; CrumbTrayMaker.goldStock=6; CrumbTrayMaker.jewelStock=4; CrumbTrayMaker.pearlStock=4; CrumbTrayMaker.productStock={}; CrumbTrayMaker.buildings={}; CrumbTrayMaker.maker=nil; CrumbTrayMaker.activeMaking={}; CrumbTrayMaker.totalProducts=0; CrumbTrayMaker.dayTimer=0; print("[CrumbTrayMaker] Royal Crumb Tray Maker System initialized (6 products, 4 buildings)") end
function CrumbTrayMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrumbTrayMaker.maker={name=n or ("Pladnjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pladnjar najet: %s (spretnost: %d)",CrumbTrayMaker.maker.name,s),"success") end; return true end
function CrumbTrayMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrumbTrayMaker.build(id) local ok,e=CrumbTrayMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrumbTrayMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrumbTrayMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrumbTrayMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrumbTrayMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CrumbTrayMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CrumbTrayMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CrumbTrayMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CrumbTrayMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CrumbTrayMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrumbTrayMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrumbTrayMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrumbTrayMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrumbTrayMaker.buildings==0 then return false,"Potrebna pladnjska delavnica" end; if not CrumbTrayMaker.maker then return false,"Potreben pladnjar" end; return true end
function CrumbTrayMaker.make(pt,qty) qty=qty or 1; local ok,e=CrumbTrayMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CrumbTrayMaker.ironStock=CrumbTrayMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CrumbTrayMaker.bronzeStock=CrumbTrayMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CrumbTrayMaker.woodStock=CrumbTrayMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CrumbTrayMaker.leatherStock=CrumbTrayMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CrumbTrayMaker.silverStock=CrumbTrayMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrumbTrayMaker.goldStock=CrumbTrayMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrumbTrayMaker.jewelStock=CrumbTrayMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrumbTrayMaker.pearlStock=CrumbTrayMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrumbTrayMaker.maker then t=math.max(1,t-math.floor(CrumbTrayMaker.maker.skill/13)) end; table.insert(CrumbTrayMaker.activeMaking,{id="crumbtray_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrumbTrayMaker.completeMaking(m) local q=1.0+(CrumbTrayMaker.getQualityBonus()/100); if CrumbTrayMaker.maker then q=q+(CrumbTrayMaker.maker.skill/140) end; q=math.min(2.5,q); CrumbTrayMaker.productStock[m.productType]=(CrumbTrayMaker.productStock[m.productType] or 0)+m.quantity; CrumbTrayMaker.totalProducts=CrumbTrayMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrumbTrayMaker.maker then CrumbTrayMaker.maker.itemsMade=CrumbTrayMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrumbTrayMaker.maker.skill=math.min(100,CrumbTrayMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pladenj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crumbtray.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CrumbTrayMaker.update(dt) if not _G.state then return end; CrumbTrayMaker.dayTimer=CrumbTrayMaker.dayTimer+dt; if CrumbTrayMaker.dayTimer>=30 then CrumbTrayMaker.dayTimer=0; for i=#CrumbTrayMaker.activeMaking,1,-1 do local m=CrumbTrayMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrumbTrayMaker.completeMaking(m); table.remove(CrumbTrayMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrumbTrayMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrumbTrayMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrumbTrayMaker.getStats() return {ironStock=CrumbTrayMaker.ironStock,bronzeStock=CrumbTrayMaker.bronzeStock,woodStock=CrumbTrayMaker.woodStock,leatherStock=CrumbTrayMaker.leatherStock,silverStock=CrumbTrayMaker.silverStock,goldStock=CrumbTrayMaker.goldStock,jewelStock=CrumbTrayMaker.jewelStock,pearlStock=CrumbTrayMaker.pearlStock,productStock=CrumbTrayMaker.productStock,numBuildings=#CrumbTrayMaker.buildings,hasMaker=CrumbTrayMaker.maker~=nil,makerName=CrumbTrayMaker.maker and CrumbTrayMaker.maker.name or "—",makerSkill=CrumbTrayMaker.maker and CrumbTrayMaker.maker.skill or 0,activeMaking=#CrumbTrayMaker.activeMaking,totalProducts=CrumbTrayMaker.totalProducts} end
return CrumbTrayMaker
